array_types.code:
type Contents is
  array (Source_Id range <>, Source_Position range <>) of Byte
with Ghost => Static;

record_types.code:
type Piece is record
   Source : Source_Id;
   Start  : Source_Position;
   Count  : Offset;
   First  : Offset;
end record;

subprograms.code:
function Byte_At
  (C      : Contents;
   M      : Pieces;
   Length : Offset;
   P      : I64) return Byte

procedure Lemma_Absolute
  (C      : Contents;
   M      : Pieces;
   Length : Offset;
   P      : I64;
   I      : Positive)

procedure Lemma_Padding
  (C      : Contents;
   M      : Pieces;
   Length : Offset;
   P      : I64)

function Selects
  (C      : Contents;
   M      : Pieces;
   Length : Offset;
   P      : I64;
   V      : Byte) return Boolean
